def calc(promo, limit, f=0):
    d0 = ["CryptoBot", "xRocket", "0.3 %", "2.5 %", 300, CB_PROMO] if promo else ["CryptoBot", "xRocket", "2.5 %", "", 0, CB]
    return {"a": A, "d": [d0, ["xRocket", "CryptoBot", "1.5 %", "", 0, XR]], "i": INV, "l": limit, "m": "0.10", "u": "14:05", "f": f}


def order(st, **kw):
    base = {"st": st, "in": "100.00", "out": "97.50", "fee": "2.50", "pct": "2.5 %", "src": "CryptoBot", "dst": "xRocket", "id": "K7M2Q9XR4T", "t0": "@-3", "t1": 0}
    base.update(kw)
    return base


